import itertools

# Helper functions to convert times.
def minutes_to_timestr(m):
    # Convert minutes (since midnight) to a string in h:MMAM/PM format.
    hour = m // 60
    minute = m % 60
    suffix = "AM" if hour < 12 else "PM"
    hour_display = hour if 1 <= hour <= 12 else (hour-12 if hour>12 else 12)
    return f"{hour_display}:{minute:02d}{suffix}"

