# Simulate a given route of friend meetings.
def simulate_route(route):
    schedule = []
    current_time = 540  # 9:00AM in minutes after midnight.
    current_location = "Marina District"
    schedule.append(f"You start at {current_location} at {minutes_to_timestr(current_time)}.")

    for friend in route:
        friend_data = friends[friend]
        destination = friend_data["district"]
        # Get travel time from current location to destination:
        travel_time = travel[current_location][destination]
        arrival_time = current_time + travel_time
        schedule.append(f"You travel to {destination} in {travel_time} minutes and arrive at {minutes_to_timestr(arrival_time)}.")

        # Wait if arrived before friend is available
        meeting_start = max(arrival_time, friend_data["avail_start"])
        if arrival_time < friend_data["avail_start"]:
            schedule.append(f"You wait until {minutes_to_timestr(meeting_start)}.")

        meeting_end = meeting_start + friend_data["duration"]
        # Check feasibility: meeting must finish before or exactly at available end.
        if meeting_end > friend_data["avail_end"]:
            # The route is not feasible for this friend – return the schedule so far.
            return schedule, False, route.index(friend)

        schedule.append(f"You meet {friend} for {friend_data['duration']} minutes from {minutes_to_timestr(meeting_start)} to {minutes_to_timestr(meeting_end)}.")
        current_time = meeting_end
        current_location = destination
    return schedule, True, len(route)

# Brute-force search over orders (permutations) to maximize number of meetings.
friend_names = list(friends.keys())
best_schedule = None
max_count = 0

for perm in itertools.permutations(friend_names):
    schedule_lines, feasible, count = simulate_route(perm)
    # Even if not all meetings in perm are feasible, we count the consecutive prefix that worked.
    if count > max_count:
        max_count = count
        best_schedule = schedule_lines
    # Early exit: if we get all 9 friends then that is maximum.
    if max_count == len(friend_names):
        break

# In our problem it turns out that Elizabeth cannot be met (so max_count is likely 8).
print(best_schedule)

def format_time(time_minutes):
    """
    Convert minutes since midnight to a time string (e.g. "9:00AM", "2:30PM").
    """
    hour = time_minutes // 60
    minute = time_minutes % 60
    suffix = "AM" if hour < 12 else "PM"
    # Convert 0 hour to 12 for display; also adjust hours above 12.
    display_hour = hour if 1 <= hour <= 12 else (hour-12 if hour > 12 else 12)
    return f"{display_hour}:{minute:02d}{suffix}"


