# Global variables to store the best (maximum friends met) itinerary
best_itinerary = []
max_friends = 0

def dfs(current_location, current_time, visited, itinerary):
    global best_itinerary, max_friends

    has_next = False
    # Try scheduling each friend not yet visited.
    for friend_name, details in friends.items():
        if friend_name in visited:
            continue
        # Travel from current_location to friend’s location.
        travel_time = distances[current_location][details["location"]]
        arrival_time = current_time + travel_time

        # Meeting start is the later of arrival time and friend’s availability start.
        meeting_start = max(arrival_time, details["start"])
        meeting_end = meeting_start + details["duration"]

        # Check if meeting can finish before the friend leaves.
        if meeting_end > details["end"]:
            continue  # cannot schedule this friend

        # Make a copy of itinerary for this branch.
        new_itinerary = itinerary.copy()
        travel_line = f"You travel to {details['location']} in {travel_time} minutes and arrive at {format_time(arrival_time)}."
        new_itinerary.append(travel_line)

        # Add a waiting message if arriving early.
        if arrival_time < details["start"]:
            wait_line = f"You wait until {format_time(details['start'])}."
            new_itinerary.append(wait_line)

        meet_line = (f"You meet {friend_name} for {details['duration']} minutes "
                     f"from {format_time(meeting_start)} to {format_time(meeting_end)}.")
        new_itinerary.append(meet_line)

        # Mark this friend as visited and recursively continue.
        visited.add(friend_name)
        dfs(details["location"], meeting_end, visited, new_itinerary)
        visited.remove(friend_name)
        has_next = True

    # If no further friend can be scheduled, update the best itinerary if needed.
    if not has_next:
        if len(visited) > max_friends:
            max_friends = len(visited)
            best_itinerary = itinerary.copy()

def main():
    # Start at Mission District at 9:00AM (9*60=540 minutes).
    start_time = 9 * 60  # 540 minutes
    initial_itinerary = [f"You start at Mission District at {format_time(start_time)}."]
    visited = set()
    dfs("Mission District", start_time, visited, initial_itinerary)

    # Output the best itinerary (as a list of strings).
    print(best_itinerary)

if __name__ == "__main__":
    main()

